mapper.insert:
INSERT INTO `voucher_order` (
    user_id, voucher_id, status, order_no, pay_amount, payment_method, payment_status, order_source, pay_deadline, use_deadline, create_time
) VALUES (
    #{userId}, #{voucherId}, #{status}, #{orderNo}, #{payAmount}, #{paymentMethod}, #{paymentStatus}, #{orderSource}, #{payDeadline}, #{useDeadline}, NOW()
)

mapper.select:
SELECT * FROM `voucher_order`
WHERE user_id = #{userId}
ORDER BY create_time DESC

SELECT * FROM `voucher_order`
WHERE voucher_id = #{voucherId}
ORDER BY create_time DESC

SELECT COUNT(1)
FROM `voucher_order`
WHERE user_id = #{userId} AND voucher_id = #{voucherId}

SELECT COUNT(1)
FROM `voucher_order`
WHERE user_id = #{userId}
  AND voucher_id = #{voucherId}
  AND status <> 5

SELECT

FROM `voucher_order` vo
LEFT JOIN `voucher` v ON vo.voucher_id = v.id
LEFT JOIN `merchant` m ON v.merchant_id = m.id
WHERE vo.user_id = #{userId}

    AND vo.status = #{status}

ORDER BY vo.create_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM `voucher_order` vo
WHERE vo.user_id = #{userId}

    AND vo.status = #{status}

mapper.update:
UPDATE `voucher_order`
SET
    status = 5,
    payment_status = 2,
    cancel_reason = #{cancelReason},
    update_time = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 0
  AND update_time = #{expectedUpdateTime}

UPDATE `voucher_order`
SET payment_idempotency_key = #{idempotencyKey}
WHERE id = #{id}
  AND status = 0
  AND payment_status = 0
  AND (payment_idempotency_key IS NULL OR payment_idempotency_key = #{idempotencyKey})

mapper.select:
SELECT COUNT(1)
FROM `voucher_order`
WHERE create_time >= #{since}

SELECT DATE(create_time) AS day, COUNT(1) AS value
FROM `voucher_order`
WHERE create_time >= #{startTime}
  AND create_time <= #{endTime}
GROUP BY DATE(create_time)
ORDER BY day ASC
